{"command": "for query_id in Q000 Q001 Q002 Q003 Q004 Q005 Q006 Q007 Q008 Q009 Q010 Q011 Q012 Q013 Q014 Q015 Q016 Q017 Q018 Q019 Q020 Q021 Q022 Q023 Q024; do
  embedding=$(grep "^$query_id," data/queries.csv | cut -d',' -f2);
  echo "Querying for $query_id with embedding $embedding";
  result=$(databricks vector-search-indexes query-index --index-name workspace.mlpab740746.items568016_index --query-vector "$embedding" --num-results 5 --output JSON);
  item_ids=$(echo "$result" | jq -r '.result.data_array[].primary_key');
  echo "$query_id: [$item_ids]" >> submission/answers_temp.json;
  echo "," >> submission/answers_temp.json;
done"}

